// Scene-first puzzles. Every rule describes an action in the room, not an evidence-card match.
export const roomList=[['bedroom','윤의 침실','편지가 남긴 첫 부탁'],['observatory','별 관측실','빛이 가리키는 방향'],['workshop','수선 작업실','고장 난 것들의 쓸모'],['archive','기록 보관실','배달되지 않은 약속'],['music','작은 음악실','멜로디를 기억하는 집'],['greenhouse','유리 온실','오늘 밤의 작은 개장식']];
export const tools={key:['작은 황동 열쇠',4],oil:['기름병',5],cloth:['마른 천',6],oiled:['기름 묻힌 천',6],lens:['확대 렌즈',7],magnet:['말굽 자석',8],wire:['구리 철사',9],line:['철사 달린 자석',10],mirror:['손거울',11],wedge:['나무 쐐기',12],gear:['황동 톱니',13],roll:['구멍 악보',14],crank:['태엽 손잡이',15],letter:['윤의 편지',2,'old'],card:['출입 카드',11,'old'],score:['멜로디 쪽지',13,'old'],seal:['별빛 조각',4,'old'],watch:['회중시계',0,'old']};
const obj=(id,name,x,y,extra={})=>({id,name,x,y,...extra});
const prop=(id,name,art,x,y,extra={})=>obj(id,name,x,y,{art,...extra});
const tap=(target,set,msg,extra={})=>({action:'tap',target,set,msg,...extra});
const use=(item,target,set,msg,extra={})=>({action:'use',item,target,set,msg,...extra});
const join=(a,b,out,msg)=>({action:'combine',items:[a,b],grant:out,set:'combined',msg,consume:[a,b]});
const pick=(item,x,y,extra={})=>prop(item,tools[item][0],tools[item][1],x,y,{tool:item,...extra});
function chest(item,x=48,y=72,id='chest'){return [prop(id,'작은 상자',0,x,y,{openArt:1,openFlag:id+'_open',width:23}),pick(item,x,y-8,{need:[id+'_open'],hide:[item+'_taken']})];}
function open(id='chest',msg='단추가 뚜껑을 열었어. 안에 물건이 있어!'){return tap(id,id+'_open',msg,{pose:6});}
function take(item,need=[]){return tap(item,item+'_taken',`${tools[item][0]} 획득! 아래 소지품에서 골라 사용할 수 있어.`,{need,grant:item,pose:7});}
const finish=(target,msg,need=[])=>tap(target,'done',msg,{need,pose:7});
const stages=[];
function add(title,goal,story,objects,rules,hints,extra={}){stages.push({id:stages.length+1,room:Math.floor(stages.length/5),title,goal,story,objects,rules,hints,...extra});}
add('잠긴 편지','상자 속 열쇠로 편지 서랍을 열어줘.','윤이 온실로 와 달라는 쪽지를 남겼어. 그런데 자세한 편지는 서랍 안에 있네.',[...chest('key'),obj('drawer','편지 서랍',85,52,{symbol:'▤',detail:'작은 황동 열쇠 구멍이 있어.'}),pick('letter',83,43,{need:['unlocked'],hide:['letter_taken']})],[open(),take('key'),use('key','drawer','unlocked','찰칵! 단추가 서랍을 당겼어. 윤의 편지가 보여.',{consume:['key']}),tap('letter','done','“폐관한 온실을 오늘 밤 다시 열 거야. 먼저 안쪽 문을 열어 줘.”',{need:['unlocked'],grant:'letter'})],['가운데 작은 상자는 뚜껑이 들릴 것 같아.','열쇠를 얻은 뒤 아래 소지품 → 편지 서랍 순서로 눌러 봐.']);
add('열쇠보다 먼저','뻑뻑한 문 경첩을 부드럽게 해줘.','열쇠는 맞는데 문이 움직이지 않아. 윤이 오래 비워 둔 집이거든.',[...chest('oil',44,72),pick('cloth',25,53),obj('hinge','녹슨 경첩',91,49,{symbol:'⚙',detail:'기름을 그냥 붓기엔 틈이 너무 좁아. 천으로 바르면 닿겠어.'}),obj('door','안쪽 문',92,66,{symbol:'↗'})],[open(),take('oil'),take('cloth'),join('oil','cloth','oiled','천 끝에 기름을 묻혔어. 좁은 틈도 닦을 수 있겠다.'),use('oiled','hinge','smooth','삐걱거리던 경첩이 조용해졌어.',{consume:['oiled']}),finish('door','문이 열렸어. 바람이 별 관측실에서 불어와.', ['smooth'])],['기름병과 천을 함께 쓸 방법이 있을까?','소지품 두 개를 선택하고 조합한 뒤 경첩에 사용해 봐.']);
add('바람이 가져간 쪽지','침대 밑으로 들어간 쪽지를 꺼내줘.','문을 여니 편지의 마지막 장이 침대 밑으로 날아갔어.',[...chest('wire'),pick('magnet',79,55),obj('gap','침대 아래 틈',25,69,{symbol:'⌁',detail:'쪽지에 금속 클립이 꽂혀 있어. 손은 닿지 않아.'}),pick('letter',26,62,{need:['pulled'],hide:['letter_taken']})],[open(),take('wire'),take('magnet'),join('magnet','wire','line','철사를 매달면 자석을 침대 깊숙이 넣을 수 있어.'),use('line','gap','pulled','딸깍! 클립에 자석이 붙었어. 단추가 쪽지를 끌어냈어.'),tap('letter','done','쪽지: “온실의 별빛 장치는 빛·톱니·음악으로 깨어나.”',{need:['pulled']})],['쪽지의 금속 클립을 이용해 보자.','철사와 자석을 조합하면 멀리 있는 금속을 꺼낼 수 있어.']);
add('시계의 작은 비밀','시계 그림에 숨은 서랍 번호를 찾아줘.','윤은 번호를 잊지 않으려고 그림 속에 남기곤 했대.',[pick('lens',83,53),obj('clock','벽시계의 작은 그림',53,22,{symbol:'◷',detail:'시계 유리 가장자리에 아주 작은 숫자 세 개가 새겨져 있어.'}),obj('lock','세 자리 서랍',48,63,{symbol:'▦',pad:true,answer:'314',clue:'확대하면 읽을 수 있어.',requires:['read']})],[take('lens'),use('lens','clock','read','확대하니 새겨진 숫자가 보여: 3 · 1 · 4',{reveal:'3 · 1 · 4'}),{action:'code',target:'lock',answer:'314',need:['read'],set:'done',msg:'서랍 안의 기록: “멈춘 시계는 정답이 아니라 안내판.”'}],['시계의 바늘보다 유리 가장자리의 작은 글씨를 보자.','렌즈를 얻어 시계에 사용하면 번호를 읽을 수 있어.']);
add('문이 자꾸 닫혀','바람에 닫히는 문을 고정하고 나가줘.','안쪽 통로를 찾았지만 발을 떼면 문이 닫혀. 윤도 이 문 때문에 고생했겠어.',[...chest('wedge'),obj('door','바람에 닫히는 문',90,58,{symbol:'↗',detail:'바닥과 문 사이가 비스듬하게 벌어져 있어.'}),obj('exit','통로로 이동',91,70,{symbol:'→',need:['held']})],[open(),take('wedge'),use('wedge','door','held','쐐기를 문 아래 끼웠어. 이제 손을 놓아도 열려 있어.',{consume:['wedge']}),finish('exit','빛이 가득한 별 관측실로 들어왔어.',['held'])],['문고리 대신 문 아래 틈을 살펴봐.','쐐기를 끼워 문이 닫히지 않게 해줘.']);
add('흐릿한 별자리','먼지 낀 관측판을 닦아 별 순서를 읽어줘.','온실에 빛을 보내려면 관측실의 반사판부터 맞춰야 해.',[...chest('cloth'),obj('chart','먼지 낀 관측판',52,34,{symbol:'✧',detail:'그림 위를 먼지가 가리고 있어.'}),obj('panel','별 순서 장치',72,59,{symbol:'▦',pad:true,answer:'241',requires:['clean'],clue:'큰 별부터 작은 별 순서.  큰 별 ② / 중간 별 ④ / 작은 별 ①'})],[open(),take('cloth'),use('cloth','chart','clean','먼지가 걷혔어. 큰 별 ② → 중간 별 ④ → 작은 별 ①',{reveal:'✦ ②   ✧ ④   · ①'}),{action:'code',target:'panel',answer:'241',need:['clean'],set:'done',msg:'반사판 덮개가 열렸어. 이제 빛을 옮길 수 있어.'}],['관측판의 먼지를 먼저 닦아줘.','별 크기 순서대로 2, 4, 1을 눌러 봐.']);
add('빛은 모퉁이를 못 돌아','거울로 창가 빛을 어두운 센서에 보내줘.','센서는 벽 뒤에 있어. 렌즈로 빛을 모으기만 해서는 닿지 않아.',[...chest('mirror'),obj('beam','창가의 빛',24,36,{symbol:'☀',detail:'빛이 바닥의 작은 거치대에 닿아.'}),obj('stand','빈 거울 거치대',50,68,{symbol:'◇'}),obj('sensor','그늘 속 센서',81,54,{symbol:'◉',need:['reflected']})],[open(),take('mirror'),use('mirror','stand','reflected','거울이 빛을 옆으로 꺾었어! 센서가 반짝이기 시작해.',{consume:['mirror'],beam:true}),finish('sensor','센서가 켜졌어. 빛의 방향을 바꾸는 게 답이었네.',['reflected'])],['빛을 더 강하게 만드는 것보다 방향을 바꿔야 해.','거울을 바닥 거치대에 놓아 봐.']);
add('작은 빛 모으기','넓게 퍼진 빛을 렌즈로 모아줘.','반사된 빛은 도착했지만, 잠금판을 깨우기엔 약해.',[pick('lens',77,57),obj('holder','빛이 퍼지는 고리',51,48,{symbol:'◎'}),obj('switch','빛 잠금판',73,42,{symbol:'◉',need:['focused']})],[take('lens'),use('lens','holder','focused','렌즈가 빛을 한 점으로 모았어. 잠금판이 환해졌어.',{consume:['lens'],beam:true}),finish('switch','서쪽 통로 표시등이 켜졌어.',['focused'])],['여기선 방향보다 빛의 넓이가 문제야.','렌즈를 둥근 고리에 끼워 줘.']);
add('뒤집힌 안내','거울에 비친 번호를 바로 읽어줘.','판에 적힌 숫자가 뒤집혀 보여. 윤은 반사판을 통해 읽도록 만든 거야.',[...chest('mirror'),obj('plate','뒤집힌 숫자판',55,33,{symbol:'▧',detail:'숫자의 좌우가 거꾸로야.'}),obj('lock','관측 서랍',80,59,{symbol:'▦',pad:true,answer:'527',requires:['read'],clue:'거울로 확인한 번호: 5 · 2 · 7'})],[open(),take('mirror'),use('mirror','plate','read','거울에 비추니 똑바로 읽혀. 5 · 2 · 7',{reveal:'5 · 2 · 7'}),{action:'code',target:'lock',answer:'527',need:['read'],set:'done',msg:'윤의 설계도가 나왔어. 다음은 톱니를 수리할 차례야.'}],['뒤집힌 글씨는 거울 속에서 바로 보여.','손거울을 숫자판에 대고 번호를 확인해.']);
add('꽉 막힌 손잡이','얼어붙은 회전 손잡이를 움직여 통로를 열어줘.','빛이 가리킨 문은 손잡이가 빠져 있고 축까지 뻑뻑해.',[...chest('crank'),pick('oil',78,57),obj('axle','뻑뻑한 회전축',63,49,{symbol:'⚙'}),obj('hatch','작업실 통로',76,72,{symbol:'→',need:['turned']})],[open(),take('crank'),take('oil'),use('oil','axle','lubed','축의 녹이 풀렸어. 이제 손잡이가 돌아가겠어.'),use('crank','axle','turned','단추가 손잡이를 돌리자 통로가 열렸어.',{need:['lubed'],consume:['crank']}),finish('hatch','온실 장치를 만든 작업실이야.',['turned'])],['손잡이만 꽂으면 축이 부러질 것 같아.','기름으로 축을 먼저 부드럽게 해줘.']);
add('배수구에 빠진 톱니','빠진 톱니를 건져 기계에 끼워줘.','작업실의 첫 기계가 멈췄어. 톱니 하나가 배수구에서 반짝여.',[pick('magnet',22,51),pick('wire',39,58),obj('drain','깊은 배수구',68,76,{symbol:'⌁'}),pick('gear',68,65,{need:['retrieved'],hide:['gear_taken']}),obj('machine','빈 톱니 축',62,43,{symbol:'⚙'})],[take('magnet'),take('wire'),join('magnet','wire','line','긴 자석 낚싯줄 완성!'),use('line','drain','retrieved','단추가 배수구에서 톱니를 건졌어.'),take('gear',['retrieved']),use('gear','machine','done','톱니가 맞물려 기계가 움직이기 시작해.',{consume:['gear']})],['금속 톱니지만 손으로는 닿지 않아.','자석과 철사를 조합해 배수구에 내려 보자.']);
add('도는 쪽이 중요해','톱니가 맞물리는 방향을 찾아줘.','맞닿은 톱니는 서로 반대 방향으로 돌아. 표시등까지 힘을 보내자.',[obj('diagram','톱니 연결 도면',28,30,{symbol:'▤',detail:'① 시계 방향 → ② 반시계 방향 → ③ 시계 방향. 맞닿을 때마다 방향이 반대가 돼.'}),obj('left','③ 반시계 방향',55,56,{symbol:'↶'}),obj('right','③ 시계 방향',75,56,{symbol:'↷'}),obj('switch','기계 가동',65,70,{symbol:'▷',need:['direction']})],[tap('diagram','seen','도면: 첫 톱니는 시계 방향. 세 번째 톱니는 어느 쪽일까?',{reveal:'① ↻   ② ↺   ③ ?'}),tap('right','direction','정답! 세 번째는 다시 시계 방향이야.',{need:['seen']}),finish('switch','연결된 톱니가 부드럽게 돌아가.',['direction'])],['한 번 맞물리면 반대, 두 번이면 처음과 같아.','세 번째 톱니는 시계 방향이야.'],{wrong:{left:'반대야. 맞닿을 때마다 방향이 한 번씩 뒤집혀.'}});
add('상자를 누르는 대신','지렛대로 무거운 덮개를 들어줘.','온힘을 줘도 덮개가 안 열려. 힘을 크게 만드는 방법이 필요해.',[pick('crank',27,52),pick('wedge',44,60),obj('cover','무거운 바닥 덮개',71,74,{symbol:'▰',detail:'가장자리 아래에 작은 틈이 있어.'}),obj('inside','덮개 안 손잡이',73,63,{symbol:'↗',need:['raised']})],[take('wedge'),take('crank'),use('wedge','cover','support','쐐기로 받침점을 만들었어.',{consume:['wedge']}),use('crank','cover','raised','긴 손잡이를 지렛대로 쓰자 덮개가 들렸어!',{need:['support']}),finish('inside','밑에 숨겨진 배선 통로가 열렸어.',['raised'])],['틈에 받침점을 만들면 긴 손잡이를 지렛대로 쓸 수 있어.','쐐기 다음 손잡이 순서로 덮개에 사용해.']);
add('안 보이는 연락선','접점의 먼지를 닦고 전선을 연결해줘.','선은 끊어지지 않았어. 먼지가 접촉을 막고 있네.',[...chest('cloth'),pick('wire',29,56),obj('contact','먼지 낀 접점',66,49,{symbol:'⌁'}),obj('switch','시험 스위치',79,62,{symbol:'ϟ',need:['wired']})],[open(),take('cloth'),take('wire'),use('cloth','contact','clean','접점의 구리가 드러났어.'),use('wire','contact','wired','구리 철사를 두 접점에 연결했어.',{need:['clean'],consume:['wire']}),finish('switch','온실로 보내는 전기가 돌아왔어.',['wired'])],['전선을 바꾸기 전에 접점 상태를 보자.','천으로 닦고 철사를 연결한 뒤 시험해 봐.']);
add('돌려서 보내는 편지','태엽 우편함을 작동시켜 다음 방으로 가줘.','윤이 준비한 안내 카드는 태엽 우편함 안에 있어.',[...chest('crank'),obj('mailbox','태엽 우편함',60,47,{symbol:'✉'}),pick('card',61,37,{need:['wound'],hide:['card_taken']}),obj('reader','보관실 카드 판독기',82,66,{symbol:'▥'})],[open(),take('crank'),use('crank','mailbox','wound','손잡이를 돌리자 우편함에서 카드가 올라왔어.'),take('card',['wound']),use('card','reader','done','카드가 승인됐어. 윤이 남긴 배달 기록을 찾아보자.',{consume:['card']})],['우편함 옆의 사각 구멍에 맞는 도구를 찾아봐.','태엽 손잡이로 카드를 꺼내 판독기에 사용해.']);
add('봉투의 주인은 누구','도장과 모양이 맞는 편지함에 배달해줘.','윤의 오래된 편지는 한 곳으로 모여 있어. 도장이 같은 칸을 찾자.',[...chest('letter'),obj('stamp','배달 안내판',29,32,{symbol:'▤',detail:'봉투 도장: 별. 별 편지함은 오른쪽에 있어.'}),obj('moon','달 편지함',52,56,{symbol:'☾'}),obj('star','별 편지함',78,56,{symbol:'✧'})],[open(),take('letter'),tap('stamp','read','봉투에는 별 도장이 찍혀 있어.',{reveal:'✉ ✧  →  ✧'}),use('letter','star','done','별 편지함에서 윤의 답장이 나왔어. “음악은 모두에게 들려줘.”',{need:['read'],consume:['letter']})],['색보다 봉투의 도장 모양을 보자.','별 도장이니 별 모양 편지함에 넣어줘.'],{wrong:{moon:'달 도장 편지함이야. 봉투의 도장은 별 모양이었어.'}});
